// RoomTile is one picture on the client's page.
type RoomTile struct {
	N      int
	ID     string
	Video  bool
	Picked bool
	Mine   bool   // the original can be downloaded
	Note   string // the client's note on this photo
	Reply  string // and the photographer's answer
}

// RoomPageData is what the client's page shows.
type RoomPageData struct {
	Title, Token string
	Tiles        []RoomTile
	Name         string // the name the client gave, if any
	Count, Limit int
	CounterText  string
	Done         bool
	CanPick      bool
	NeedsName    bool   // a named room nobody has claimed
	Chooser      string // a named room somebody else has claimed: who
	Mode         string
	Message      string // what went wrong with the last press, in words
	Released     bool   // the originals of this client's sent choice can be downloaded
	Until        string // until when, "" for as long as the room works
	Notes        string // notes on photos: "", "note" or "replies"
	Round, Total int    // the round the room is in, and how many photos the room has in all
}

