// ReviewData is the photographer's page for the choices clients sent in a room.
type ReviewData struct {
	User, ID, Name string
	Selections     []ReviewSel
	Released       bool
	ReleasedAt     string
	Until          string
	Downloads      int
	Auto           bool
	Limit          int
	Replies        bool // the photographer may answer notes
	Round          int
	Several        bool // the room goes through several rounds
	CanStart       bool // a next round may be started
	History        []HistoryRound
}

// HistoryRound is a round that is over, for the review page.
type HistoryRound struct {
	Round int
	Lines []string
}

// ReviewSel is one selection on the review page.
type ReviewSel struct {
	Name, When string
	Done       bool
	Photos     []ReviewPhoto
	Names      string // the file names, one on each line
	Chosen     int
}

// ReviewPhoto is one chosen photo on the review page.
type ReviewPhoto struct {
	N      int
	ID     string
	File   string
	Who    string // the selection's mark, for answering
	Chosen bool   // in the choice (not only noted)
	Note   string
	Reply  string
}

